mapper.select:
SELECT A.NO AS no, TYPE AS type, NAME AS name, A.USER_ID AS userId, DEPTCD AS deptCd, DEPTNM AS deptNm, DATE_FORMAT(EXPIRATION_DT, '%Y-%m-%d' ) AS edate, ATTACHED_YN AS attachedYn, SEARCH_YN AS searchYn, DATE_FORMAT(CREATE_DT, '%Y-%m-%d' ) AS createDt, CREATE_ID AS createId, CREATE_NAME AS createNm, PURPOSE AS purpose, FILE_PATH AS filePath, APPCD AS appCd, FILE_NAME AS fileName, ALARM_YN AS alarmYn, REGISTRANT_YN AS registrantYn, ALARM_MAIL_YN AS alarmMailYn, ALARM_SMS_YN AS alarmSmsYn, ALARM_MONITOR_YN AS alarmMonitorYn, GROUP_CONCAT(DISTINCT B.IP ORDER BY B.IP SEPARATOR ',') AS userIp, GROUP_CONCAT(DISTINCT
CAST(if(C.USER_EMAIL is null, null, xcndec(#{encryptAlgorithm}, #{encryptSize}, #{encryptKey}, C.USER_EMAIL)) AS CHAR)
C.USER_EMAIL
ORDER BY C.USER_EMAIL SEPARATOR ',') AS userEmail FROM UI_CONSENT A LEFT OUTER JOIN UI_CONSENT_IP B ON A.NO = B.NO LEFT OUTER JOIN UI_USER_EMAIL C ON A.USER_ID = C.USER_ID WHERE DATE_FORMAT(CREATE_DT, '%Y-%m-%d' ) BETWEEN DATE_FORMAT(#{startDate}, '%Y-%m-%d' ) AND DATE_FORMAT(#{endDate}, '%Y-%m-%d' )
AND TYPE = #{type}
AND APPCD = #{consentStatus}
AND CREATE_NAME LIKE CONCAT('%', #{createNm}, '%')
AND NAME LIKE CONCAT('%', #{searchStr}, '%')
GROUP BY A.NO, TYPE, NAME, A.USER_ID, DEPTCD, DEPTNM, DATE_FORMAT(EXPIRATION_DT, '%Y-%m-%d' ), ATTACHED_YN, SEARCH_YN, DATE_FORMAT(CREATE_DT, '%Y-%m-%d %T' ), CREATE_ID, CREATE_NAME, PURPOSE, FILE_PATH, APPCD, FILE_NAME, ALARM_YN, REGISTRANT_YN, ALARM_MAIL_YN, ALARM_SMS_YN, ALARM_MONITOR_YN ORDER BY NO DESC
LIMIT ${offset}, ${limit}

SELECT  FILE_PATH AS filePath, FILE_NAME AS fileName, ATTACHED_YN AS attachedYn, APPCD AS appCd
FROM	UI_CONSENT
WHERE	NO = #{no}

mapper.delete:
DELETE	FROM	UI_BUSI_IPRANGE 
WHERE	BUSICD 		= #{busiCd}
AND		START_IP 	= #{startIp}
AND		END_IP 		= #{endIp}

mapper.update:
UPDATE	UI_CONSENT
SET		APPCD = #{appCd}
WHERE	NO = #{no}

mapper.select:
SELECT	APPROBATOR
FROM	UI_ADMIN
WHERE	ADMIN_ID = #{adminId}
